import {
    Table,
    ReferenceColumn,
    DateTimeColumn,
    GenericColumn,
    ConditionsColumn,
    StringColumn,
    SystemClassNameColumn,
    IntegerColumn,
} from '@servicenow/sdk/core'

export const sys_ui_related_list_entry = Table({
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.forcePrimaryKeyOrdering': true,
        forcePrimaryKeyOrdering: true,
        no_audit_delete: true,
        scope_master: 'list_id',
    },
    display: 'related_list',
    extensible: true,
    label: 'Related List Entry',
    name: 'sys_ui_related_list_entry',
    schema: {
        list_id: ReferenceColumn({
            cascadeRule: 'delete',
            label: 'List ID',
            referenceTable: 'sys_ui_related_list',
        }),
        sys_updated_on: DateTimeColumn({
            label: 'Updated',
        }),
        sys_id: GenericColumn({
            columnType: 'GUID',
            label: 'Sys ID',
            maxLength: 32,
            primary: true,
        }),
        filter: ConditionsColumn({
            dynamicValueDefinitions: {
                type: 'dependent_field',
                columnName: 'related_list',
            },
            label: 'Filter',
            maxLength: 3500,
        }),
        related_list: StringColumn({
            label: 'Related list',
            maxLength: 165,
        }),
        sys_created_on: DateTimeColumn({
            label: 'Created',
        }),
        sys_class_name: SystemClassNameColumn({
            default: 'javascript:current.getTableName();',
            dropdown: 'dropdown_without_none',
            label: 'Class',
            maxLength: 80,
        }),
        sys_updated_by: StringColumn({
            label: 'Updated by',
        }),
        order_by: StringColumn({
            label: [
                {
                    hint: 'Default order by field for related list',
                    label: 'Order by',
                    plural: 'Order by',
                    language: 'en',
                },
            ],
        }),
        sys_mod_count: IntegerColumn({
            label: 'Updates',
        }),
        position: IntegerColumn({
            label: 'Position',
        }),
        sys_created_by: StringColumn({
            label: 'Created by',
        }),
    },
})
